<template><section class="note-list"><div v-if="!filtered.length" class="empty">还没有笔记</div><article v-for="n in filtered" :key="n.id" class="note-item" :class="{active:n.id===notes.currentId}" @click="notes.currentId=n.id"><div class="note-title">{{n.title||'无标题'}}</div><div class="note-summary">{{n.summary}}</div><button aria-label="删除" class="delete" @click.stop="notes.trash(n.id)">删除</button></article></section></template><script setup lang="ts">import {computed} from 'vue';import {useNotesStore} from '../stores/notes';import {useUiStore} from '../stores/ui';import {useGroupsStore} from '../stores/groups';const notes=useNotesStore(),ui=useUiStore(),groups=useGroupsStore();const filtered=computed(()=>notes.items.filter(n=>ui.view==='trash'?n.invalid:!n.invalid).filter(n=>!groups.selected||n.group_id===groups.selected).filter(n=>!ui.query||(n.title+n.body).toLowerCase().includes(ui.query.toLowerCase())).sort((a,b)=>b.top-a.top||b.update_time-a.update_time))</script>
